<div class="mb-3"><label class="form-label" for="<?= e($prefix) ?>-enunciado">Enunciado *</label><textarea class="form-control" id="<?= e($prefix) ?>-enunciado" name="enunciado" required maxlength="4000" rows="3"><?= e($question['enunciado'] ?? '') ?></textarea></div>
<div class="row g-3"><?php foreach (['a','b','c','d'] as $option): ?><div class="col-md-6"><label class="form-label" for="<?= e($prefix.'-'.$option) ?>">Opción <?= e(strtoupper($option)) ?><?= in_array($option,['a','b'],true) ? ' *' : '' ?></label><input class="form-control" id="<?= e($prefix.'-'.$option) ?>" name="opcion_<?= e($option) ?>" maxlength="255" <?= in_array($option,['a','b'],true) ? 'required' : '' ?> value="<?= e($question['opcion_'.$option] ?? '') ?>"></div><?php endforeach; ?></div>
<div class="mt-3"><label class="form-label" for="<?= e($prefix) ?>-correcta">Respuesta correcta *</label><select class="form-select" name="correcta" id="<?= e($prefix) ?>-correcta" required><option value="">Seleccionar</option><?php foreach (['a','b','c','d'] as $option): ?><option value="<?= e($option) ?>" <?= ($question['correcta'] ?? '')===$option ? 'selected' : '' ?>><?= e(strtoupper($option)) ?></option><?php endforeach; ?></select></div>
